00101 
00102 Encoder::Encoder(const ImageDescription &image_description, const Parameters &parameters) {
00103     memset(&encoder_configuration_, 0, sizeof(encoder_configuration_));
00104     memset(&configuration_, 0, sizeof(configuration_));
00105 
00106     // Build default parameters
00107     auto pb = Parameters::build();
00108     Parameters defaults = parameter_defaults_global(parameters);
00109 
00110     // Set base QP param as calculated before....
00111     encoder_configuration_.base_qp = parameters["qp"].get<unsigned>(defaults);
00112 
00113     update_global_configuration(parameters, defaults, image_description);
00114 
00115     // Build image descriptions
00116     src_image_description_ = image_description;
00117     base_image_description_ = ImageDescription(image_description.format(), dimensions_.base_width(), dimensions_.base_height())
00118                                   .with_depth(configuration_.global_configuration.base_depth);
00119     intermediate_image_description_ = ImageDescription(
00120         configuration_.global_configuration.level1_depth_flag ? src_image_description_.format() : base_image_description_.format(),
00121         dimensions_.intermediate_width(), dimensions_.intermediate_height());
00122 
00123     enhancement_image_description_ =
00124         ImageDescription(image_description.format(), dimensions_.conformant_width(), dimensions_.conformant_height());
00125 }
00126 
00127 void Encoder::initialise_config(const Parameters &parameters, std::vector<std::unique_ptr<Image>> &src_image) {
00128     // Build default parameters
00129     auto pb = Parameters::build();
00130     Parameters defaults = parameter_defaults_picture(parameters, src_image, encoder_configuration_.base_qp);
00131 
00132     // Update Transform Type
00133     if (!defaults["encoding_transform_type"].empty()) {
00134         if (defaults["encoding_transform_type"].get<std::string>() == "dd") {
00135             configuration_.global_configuration.transform_block_size = 2;
00136             configuration_.global_configuration.num_residual_layers = 4;
00137 
00138             // Update image descriptions (conformance window might change with new transform)
00139             dimensions_.set(configuration_, src_image_description_.width(), src_image_description_.height());
00140             configuration_.global_configuration.resolution_width = dimensions_.conformant_width();
00141             configuration_.global_configuration.resolution_height = dimensions_.conformant_height();
00142             base_image_description_ = base_image_description_.with_size(dimensions_.base_width(), dimensions_.base_height());
00143             intermediate_image_description_ =
00144                 intermediate_image_description_.with_size(dimensions_.intermediate_width(), dimensions_.intermediate_height());
00145             enhancement_image_description_ =
00146                 enhancement_image_description_.with_size(dimensions_.conformant_width(), dimensions_.conformant_height());
00147 
00148         } else if (defaults["encoding_transform_type"].get<std::string>() == "dds") {
00149             configuration_.global_configuration.transform_block_size = 4;
00150             configuration_.global_configuration.num_residual_layers = 16;
00151         }
00152     }
00153 
00154     update_sequence_configuration(parameters, defaults, src_image_description_);
00155     update_encoder_configuration(parameters, defaults);
00156     update_picture_configuration(parameters, defaults);
00157 
00158     const unsigned step_width_2 = defaults["cq_step_width_loq_2"].get<unsigned>(MAX_STEP_WIDTH);
00159     if (step_width_2 != (unsigned)MAX_STEP_WIDTH) {
00160         configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] =
00161             clamp(step_width_2, (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
00162         configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2] =
00163             clamp(step_width_2, (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
00164     }
00165     if (parameters["temporal_step_width_modifier"].empty()) {
00166         configuration_.global_configuration.temporal_step_width_modifier =
00167             defaults["temporal_step_width_modifier"].get<unsigned>(48);
00168     }
00169     if (parameters["encoding_upsample"].empty()) {
00170         const Upsample upsample = defaults["encoding_upsample"].get_enum<Upsample>(Upsample_ModifiedCubic);
00171         configuration_.global_configuration.upsample = upsample;
00172         if (upsample == Upsample_AdaptiveCubic) {
00173             defaults["upsampling_coefficients"].get_vector<unsigned>(
00174                 configuration_.global_configuration.upsampling_coefficients,
00175                 ARRAY_SIZE(configuration_.global_configuration.upsampling_coefficients));
00176         }
00177     }
00178 
00179     // Initialize quantization matrix
00180     std::fill_n(&quant_matrix_coeffs_[0][0][0], MAX_NUM_PLANES * MAX_NUM_LOQS * MAX_NUM_LAYERS, -1);
00181 
00182     // Report final configurations
00183     REPORT("#### #### encoding_transform_type %4d", configuration_.global_configuration.transform_block_size);
00184     REPORT("#### #### num_processed_planes %4d", configuration_.global_configuration.num_processed_planes);
00185     REPORT("#### #### dequant_offset_mode %4d", configuration_.picture_configuration.dequant_offset_mode);
00186     REPORT("#### #### dequant_offset  %4d", configuration_.picture_configuration.dequant_offset);
00187     REPORT("#### #### temporal_cq_sw_multiplier %4d", encoder_configuration_.temporal_cq_sw_multiplier);
00188     REPORT("#### #### temporal_step_width_modifier %4d", configuration_.global_configuration.temporal_step_width_modifier);
00189     // REPORT("#### #### priority_mode %s", parameters["priority_mode"].get<std::string>().c_str());
00190     REPORT("#### #### encoding_upsample %4d", configuration_.global_configuration.upsample);
00191     REPORT("#### #### upsampling_coefficients %4d %4d %4d %4d", configuration_.global_configuration.upsampling_coefficients[0],
00192            configuration_.global_configuration.upsampling_coefficients[1],
00193            configuration_.global_configuration.upsampling_coefficients[2],
00194            configuration_.global_configuration.upsampling_coefficients[3]);
00195     REPORT("#### #### SW1 %4d", configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_1]);
00196     REPORT("#### #### SW2 %4d", configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2]);
00197     REPORT("#### #### quant_matrix_mode %4d", configuration_.picture_configuration.quant_matrix_mode);
00198     REPORT("#### #### qm_coefficient_1 %4d %4d %4d %4d", configuration_.picture_configuration.qm_coefficient_1_par[0],
00199            configuration_.picture_configuration.qm_coefficient_1_par[1],
00200            configuration_.picture_configuration.qm_coefficient_1_par[2],
00201            configuration_.picture_configuration.qm_coefficient_1_par[3]);
00202     REPORT("#### #### qm_coefficient_2 %4d %4d %4d %4d", configuration_.picture_configuration.qm_coefficient_2_par[0],
00203            configuration_.picture_configuration.qm_coefficient_2_par[1],
00204            configuration_.picture_configuration.qm_coefficient_2_par[2],
00205            configuration_.picture_configuration.qm_coefficient_2_par[3]);
00206 }
