00208 void Encoder::update_encoder_configuration(const Parameters &p, const Parameters &d) {
00209     // Encoder only configuration - not signalled
00210     // clang-format off
00211     encoder_configuration_.temporal_cq_sw_multiplier = p["temporal_cq_sw_multiplier"].get<unsigned>(d);
00212     CHECK(encoder_configuration_.temporal_cq_sw_multiplier >= 200 && encoder_configuration_.temporal_cq_sw_multiplier <= 1000);
00213     encoder_configuration_.delta_sw_mult_gop08 = p["delta_sw_mult_gop08"].get<unsigned>(d);
00214     encoder_configuration_.delta_sw_mult_gop08 = clamp(encoder_configuration_.delta_sw_mult_gop08, (uint32_t)1000, (uint32_t)2000);
00215     encoder_configuration_.delta_sw_mult_gop04 = p["delta_sw_mult_gop04"].get<unsigned>(d);
00216     encoder_configuration_.delta_sw_mult_gop04 = clamp(encoder_configuration_.delta_sw_mult_gop04, (uint32_t)1000, (uint32_t)2000);
00217     encoder_configuration_.delta_sw_mult_gop02 = p["delta_sw_mult_gop02"].get<unsigned>(d);
00218     encoder_configuration_.delta_sw_mult_gop02 = clamp(encoder_configuration_.delta_sw_mult_gop02, (uint32_t)1000, (uint32_t)2000);
00219     encoder_configuration_.delta_sw_mult_gop01 = p["delta_sw_mult_gop01"].get<unsigned>(d);
00220     encoder_configuration_.delta_sw_mult_gop01 = clamp(encoder_configuration_.delta_sw_mult_gop01, (uint32_t)1000, (uint32_t)2000);
00221 
00222     encoder_configuration_.no_enhancement_temporal_layer = p["temporal_signalling_present"].get<bool>(false);
00223     encoder_configuration_.user_data_method = p["user_data_method"].get_enum<UserDataMethod>(UserDataMethod_Zeros);
00224 
00225     // PriorityConfiguration priority_map_config(p["priority_mode"].get<std::string>("mode_3_1"), p["priority_type_sl_1"].get<std::string>("type_4"), p["priority_type_sl_2"].get<std::string>("type_5"));
00226     PriorityConfiguration priority_map_config(p["priority_mode"].get<std::string>(d), p["priority_type_sl_1"].get<std::string>("type_4"), p["priority_type_sl_2"].get<std::string>("type_5"));
00227     encoder_configuration_.encoding_mode = priority_map_config.encoding_mode();
00228     encoder_configuration_.temporal_use_priority_map_sl_1 = priority_map_config.use_priority_map_sl_1();
00229     encoder_configuration_.temporal_use_priority_map_sl_2 = priority_map_config.use_priority_map_sl_2();
00230     encoder_configuration_.priority_type_sl_1 = priority_map_config.priority_map_type_sl_1();
00231     encoder_configuration_.priority_type_sl_2 = priority_map_config.priority_map_type_sl_2();
00232     encoder_configuration_.sad_threshold = p["sad_threshold"].get<unsigned>(d);
00233     encoder_configuration_.sad_coeff_threshold = p["sad_coeff_threshold"].get<unsigned>(d);
00234     encoder_configuration_.quant_reduced_deadzone = p["quant_reduced_deadzone"].get<unsigned>(d);
00235     // clang-format on
00236 }
