00238 // Per stream configuration
00239 //
00240 void Encoder::update_global_configuration(const Parameters &p, const Parameters &d, const ImageDescription &image_description) {
00241     // Signalled
00242     // clang-format off
00243     configuration_.global_configuration.enhancement_depth = image_description.bit_depth();
00244     configuration_.global_configuration.base_depth = p["base_depth"].get<unsigned>(image_description.bit_depth());
00245     configuration_.global_configuration.colourspace = image_description.colourspace();
00246 
00247     configuration_.global_configuration.num_image_planes = p["num_image_planes"].get<unsigned>(3);
00248     configuration_.global_configuration.num_processed_planes = p["num_processed_planes"].get<unsigned>(d);
00249     configuration_.global_configuration.predicted_residual_enabled = p["predicted_residual"].get<bool>(true);
00250     configuration_.global_configuration.temporal_enabled = p["temporal_enabled"].get<bool>(true);
00251     configuration_.global_configuration.temporal_tile_intra_signalling_enabled = p["temporal_use_reduced_signalling"].get<bool>(true);
00252     configuration_.global_configuration.upsample = p["encoding_upsample"].get_enum<Upsample>(Upsample_ModifiedCubic);
00253     d["upsampling_coefficients"].get_vector<unsigned>(configuration_.global_configuration.upsampling_coefficients,
00254         ARRAY_SIZE(configuration_.global_configuration.upsampling_coefficients));
00255     configuration_.global_configuration.temporal_step_width_modifier = p["temporal_step_width_modifier"].get<unsigned>(48);
00256     configuration_.global_configuration.level_1_filtering_first_coefficient = p["level_1_filtering_first_coefficient"].get<unsigned>(0);
00257     configuration_.global_configuration.level_1_filtering_second_coefficient = p["level_1_filtering_second_coefficient"].get<unsigned>(0);
00258     configuration_.global_configuration.scaling_mode[LOQ_LEVEL_1] = p["scaling_mode_level1"].get_enum<ScalingMode>(ScalingMode_None);
00259     configuration_.global_configuration.scaling_mode[LOQ_LEVEL_2] = p["scaling_mode_level2"].get_enum<ScalingMode>(ScalingMode_2D);
00260     configuration_.global_configuration.user_data_enabled = p["user_data_enabled"].get_enum<UserDataMode>(UserData_None);
00261     configuration_.global_configuration.level1_depth_flag = p["level1_depth_flag"].get<bool>(false);
00262     configuration_.global_configuration.tile_width = p["tile_width"].get<unsigned>(0);
00263     configuration_.global_configuration.tile_height = p["tile_height"].get<unsigned>(0);
00264     configuration_.global_configuration.compression_type_entropy_enabled_per_tile = p["compression_type_entropy_enabled_per_tile"].get<bool>(false);
00265     configuration_.global_configuration.compression_type_size_per_tile = p["compression_type_size_per_tile"].get_enum<CompressionType>(CompressionType_None);
00266 
00267     const TransformType transform_type = p["encoding_transform_type"].get_enum<TransformType>(TransformType_DDS);
00268     if (transform_type == TransformType_DD) {
00269         configuration_.global_configuration.transform_block_size = 2;
00270         configuration_.global_configuration.num_residual_layers = 4;
00271     } else if (transform_type == TransformType_DDS) {
00272         configuration_.global_configuration.transform_block_size = 4;
00273         configuration_.global_configuration.num_residual_layers = 16;
00274     } else {
00275         ERR("Unknown transform type");
00276     }
00277 
00278     if (configuration_.global_configuration.tile_width == 0 && configuration_.global_configuration.tile_height == 0)
00279         configuration_.global_configuration.tile_dimensions_type = TileDimensions_None;
00280     else if (configuration_.global_configuration.tile_width == 512 && configuration_.global_configuration.tile_height == 256)
00281         configuration_.global_configuration.tile_dimensions_type = TileDimensions_512x256;
00282     else if (configuration_.global_configuration.tile_width == 1024 && configuration_.global_configuration.tile_height == 512)
00283         configuration_.global_configuration.tile_dimensions_type = TileDimensions_1024x512;
00284     else
00285         configuration_.global_configuration.tile_dimensions_type = TileDimensions_Custom;
00286 
00287     if(configuration_.global_configuration.upsample == Upsample_AdaptiveCubic) {
00288         p["upsampling_coefficients"].get_vector<unsigned>(configuration_.global_configuration.upsampling_coefficients,
00289                                                           ARRAY_SIZE(configuration_.global_configuration.upsampling_coefficients));
00290     }
00291 
00292     // Work out encoded image size - conformance window will be used to produce correct decoded size
00293     dimensions_.set(configuration_, image_description.width(), image_description.height());
00294 
00295     configuration_.global_configuration.resolution_width = dimensions_.conformant_width();
00296     configuration_.global_configuration.resolution_height = dimensions_.conformant_height();
00297 
00298     configuration_.global_configuration.chroma_step_width_multiplier = p["chroma_step_width_multiplier"].get<unsigned>(64);
00299 
00300     configuration_.global_configuration.additional_info_present = p["additional_info_present"].get<bool>(false);
00301     configuration_.global_configuration.sei_message_present = p["sei_message_present"].get<bool>(false);
00302     configuration_.global_configuration.vui_message_present = p["vui_message_present"].get<bool>(false);
00303     if (configuration_.global_configuration.additional_info_present) {
00304         configuration_.additional_info.additional_info_type = p["additional_info_type"].get<unsigned>(2);
00305     }
00306 
00307     INFO("additional %4d - type %4d - sei %4d - vui %4d", configuration_.global_configuration.additional_info_present, configuration_.global_configuration.additional_info_type, 
00308          configuration_.global_configuration.sei_message_present, configuration_.global_configuration.vui_message_present);
00309 }
00310 
00311 // Per sequence configuration
00312 //
00313 void Encoder::update_sequence_configuration(const Parameters &p, const Parameters &d, const ImageDescription &image_description) {
00314     // Signalled
00315     // clang-format off
00316     configuration_.sequence_configuration.profile_idc = p["profile_idc"].get_enum<Profile>(Profile_Auto);
00317     configuration_.sequence_configuration.level_idc = p["level_idc"].get<unsigned>(0);
00318     configuration_.sequence_configuration.sublevel_idc = p["sublevel_idc"].get<unsigned>(1);
00319     configuration_.sequence_configuration.conformance_window = p["conformance_window"].get<bool>(false);
00320     configuration_.sequence_configuration.extended_profile_idc = p["extended_profile_idc"].get<unsigned>(0);
00321     configuration_.sequence_configuration.extended_level_idc = p["extended_level_idc"].get<unsigned>(0);
00322     configuration_.sequence_configuration.conf_win_left_offset = p["conf_win_left_offset"].get<unsigned>(0);
00323     configuration_.sequence_configuration.conf_win_right_offset = p["conf_win_right_offset"].get<unsigned>(0);
00324     configuration_.sequence_configuration.conf_win_top_offset = p["conf_win_top_offset"].get<unsigned>(0);
00325     configuration_.sequence_configuration.conf_win_bottom_offset = p["conf_win_bottom_offset"].get<unsigned>(0);
00326     // clang-format on
00327 
00328     // Check for correct profile and level
00329     if (configuration_.sequence_configuration.profile_idc == Profile_Auto) {
00330         if (image_description.colourspace() == Colourspace_YUV422 || image_description.colourspace() == Colourspace_YUV444) {
00331             configuration_.sequence_configuration.profile_idc = Profile_Main444;
00332             INFO("Using Main 4:4:4 Profile with chroma_format_idc %u.", (unsigned)image_description.colourspace());
00333         } else {
00334             configuration_.sequence_configuration.profile_idc = Profile_Main;
00335             INFO("Using Main Profile with chroma_format_idc %u.", (unsigned)image_description.colourspace());
00336         }
00337     } else if (configuration_.sequence_configuration.profile_idc == Profile_Main &&
00338                (image_description.colourspace() == Colourspace_YUV422 || image_description.colourspace() == Colourspace_YUV444))
00339         ERR("Colourspace not supported with selected profile (see Annex A.3)");
00340     const unsigned fps = p["fps"].get<unsigned>(50);
00341     const unsigned long output_sample_rate =
00342         configuration_.global_configuration.resolution_width * configuration_.global_configuration.resolution_height * fps;
00343     if (configuration_.sequence_configuration.level_idc == 0) {
00344         // Choose minimum level automatically
00345         if (output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_1)
00346             configuration_.sequence_configuration.level_idc = 1;
00347         else if (output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_2)
00348             configuration_.sequence_configuration.level_idc = 2;
00349         else if (output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_3)
00350             configuration_.sequence_configuration.level_idc = 3;
00351         else if (output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_4)
00352             configuration_.sequence_configuration.level_idc = 4;
00353         else
00354             ERR("Cannot detect level automatically. Output sample rate not supported by any level. (see Annex A.4)");
00355         INFO("Using Level %u.%u", configuration_.sequence_configuration.level_idc,
00356              configuration_.sequence_configuration.sublevel_idc);
00357     } else {
00358         switch (configuration_.sequence_configuration.level_idc) {
00359         case 1:
00360             CHECK(output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_1);
00361             break;
00362         case 2:
00363             CHECK(output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_2);
00364             break;
00365         case 3:
00366             CHECK(output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_3);
00367             break;
00368         case 4:
00369             CHECK(output_sample_rate <= MAX_OUTPUT_RATE_LEVEL_4);
00370             break;
00371         default:
00372             ERR("Not a supported Level (see Annex A.4)");
00373         }
00374     }
00375 
00376     if (configuration_.global_configuration.resolution_width != image_description.width() ||
00377         configuration_.global_configuration.resolution_height != image_description.height()) {
00378         INFO("Resolution has been adjusted from %ux%u to %ux%u to conform.", image_description.width(), image_description.height(),
00379              configuration_.global_configuration.resolution_width, configuration_.global_configuration.resolution_height);
00380         configuration_.sequence_configuration.conformance_window = true;
00381         configuration_.sequence_configuration.conf_win_right_offset =
00382             (configuration_.global_configuration.resolution_width - image_description.width()) / 2;
00383         configuration_.sequence_configuration.conf_win_bottom_offset =
00384             (configuration_.global_configuration.resolution_height - image_description.height()) / 2;
00385     }
00386 }
