00388 // Per picture configuration
00389 //
00390 void Encoder::update_picture_configuration(const Parameters &p, const Parameters &d) {
00391     // Signalled
00392     // clang-format off
00393     configuration_.picture_configuration.enhancement_enabled = p["enhancement"].get<bool>(true); // NB: may be overridden in encoder
00394     configuration_.picture_configuration.temporal_refresh = p["temporal_refresh"].get<bool>(false); // NB: may be overridden in encoder
00395     configuration_.picture_configuration.temporal_signalling_present = p["temporal_signalling_present"].get<bool>(true); // NB: may be overridden in encoder
00396 
00397     //configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_1] = p["cq_step_width_loq_1"].get<unsigned>(MAX_STEP_WIDTH);
00398     configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_1] = p["cq_step_width_loq_1"].get<unsigned>(d);
00399     configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_1] = clamp(configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_1], (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
00400     configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] = p["cq_step_width_loq_0"].get<unsigned>(MAX_STEP_WIDTH);
00401     configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] = clamp(configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2], (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
00402     configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_1] = p["cq_step_width_loq_1"].get<unsigned>(d);
00403     configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_1] = clamp(configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_1], (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
00404     configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2] = p["cq_step_width_loq_0"].get<unsigned>(MAX_STEP_WIDTH);
00405     configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2] = clamp(configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2], (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
00406 
00407     configuration_.picture_configuration.picture_type = p["picture_type"].get_enum<PictureType>(PictureType_Frame);
00408     configuration_.picture_configuration.field_type = FieldType_Top;
00409     configuration_.picture_configuration.coding_type = CodingType_IDR;
00410 
00411     configuration_.picture_configuration.level_1_filtering_enabled = p["level_1_filtering_enabled"].get<bool>(false);
00412 
00413     // configuration_.picture_configuration.dithering_control = p["dithering_control"].get<bool>(false);
00414     configuration_.picture_configuration.dithering_control = p["dithering_control"].get<bool>(d);
00415     // configuration_.picture_configuration.dithering_type = p["dithering_type"].get_enum<DitheringType>(Dithering_None);
00416     configuration_.picture_configuration.dithering_type = p["dithering_type"].get_enum<DitheringType>(d);
00417     // configuration_.picture_configuration.dithering_strength = p["dithering_strength"].get<unsigned>(0);
00418     configuration_.picture_configuration.dithering_strength = p["dithering_strength"].get<unsigned>(d);
00419     configuration_.picture_configuration.dequant_offset_mode = p["dequant_offset_mode"].get_enum<DequantOffset>(d);
00420     configuration_.picture_configuration.dequant_offset = p["dequant_offset"].get<int>(d);
00421 
00422     configuration_.picture_configuration.quant_matrix_mode = p["quant_matrix_mode"].get_enum<QuantMatrix>(d);
00423     d["qm_coefficient_2"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_2_par,
00424                                                 configuration_.global_configuration.num_residual_layers);
00425     d["qm_coefficient_1"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_1_par,
00426                                                 configuration_.global_configuration.num_residual_layers);
00427 
00428     // clang-format on
00429 
00430     if (configuration_.picture_configuration.dequant_offset == 0 &&
00431         configuration_.picture_configuration.dequant_offset_mode == DequantOffset_Default) {
00432         configuration_.picture_configuration.dequant_offset_signalled = false;
00433     } else {
00434         configuration_.picture_configuration.dequant_offset_signalled = true;
00435     }
00436 
00437     // first, set the QM to default values
00438     const uint8_t *d2 = nullptr;
00439     const uint8_t *d1 = nullptr;
00440     const bool horizontal_only = (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_2] == ScalingMode_1D ? true : false);
00441     if (configuration_.global_configuration.num_residual_layers == 4) {
00442         // 2x2 case
00443         d1 = default_qm_coefficient_2x2[2]; // LOQ1
00444         // 4x4 case
00445         if (horizontal_only)
00446             d2 = default_qm_coefficient_2x2[0]; // LOQ2 1D
00447         else
00448             d2 = default_qm_coefficient_2x2[1]; // LOQ2 2D
00449     } else {
00450         // 4x4 case
00451         d1 = default_qm_coefficient_4x4[2]; // LOQ1
00452         if (horizontal_only)
00453             d2 = default_qm_coefficient_4x4[0]; // LOQ2 1D
00454         else
00455             d2 = default_qm_coefficient_4x4[1]; // LOQ2 2D
00456     }
00457     for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00458         configuration_.picture_configuration.qm_coefficient_2[i] = d2[i];
00459         configuration_.picture_configuration.qm_coefficient_1[i] = d1[i];
00460     }
00461 
00462     {
00463         // set the QM to default or specific custom values
00464         if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_BothDefault) {
00465             // parameters read from input (command line or config file) initialised to default
00466             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00467                 configuration_.picture_configuration.qm_coefficient_2_par[i] = d2[i];
00468                 configuration_.picture_configuration.qm_coefficient_1_par[i] = d1[i];
00469             }
00470         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_SameAndCustom) {
00471             p["qm_coefficient_2"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_2_par,
00472                                                        configuration_.global_configuration.num_residual_layers);
00473             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00474                 configuration_.picture_configuration.qm_coefficient_1_par[i] =
00475                     configuration_.picture_configuration.qm_coefficient_2_par[i];
00476             }
00477         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_Level2CustomLevel1Default) {
00478             p["qm_coefficient_2"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_2_par,
00479                                                        configuration_.global_configuration.num_residual_layers);
00480         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_Level2DefaultLevel1Custom) {
00481             p["qm_coefficient_1"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_1_par,
00482                                                        configuration_.global_configuration.num_residual_layers);
00483         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_DifferentAndCustom) {
00484             p["qm_coefficient_2"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_2_par,
00485                                                        configuration_.global_configuration.num_residual_layers);
00486             p["qm_coefficient_1"].get_vector<unsigned>(configuration_.picture_configuration.qm_coefficient_1_par,
00487                                                        configuration_.global_configuration.num_residual_layers);
00488         }
00489     }
00490 
00491     // third, save the QM in memory for the next round
00492     for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00493         configuration_.picture_configuration.qm_coefficient_2_mem[i] = configuration_.picture_configuration.qm_coefficient_2[i];
00494         configuration_.picture_configuration.qm_coefficient_1_mem[i] = configuration_.picture_configuration.qm_coefficient_1[i];
00495     }
00496 }
