00498 // Per picture configuration (in loop)
00499 //
00500 void Encoder::update_picture_configuration_in_loop() {
00501     // first, set the QM to default values
00502     const uint8_t *d2 = nullptr;
00503     const uint8_t *d1 = nullptr;
00504     const bool horizontal_only = (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_2] == ScalingMode_1D ? true : false);
00505     if (configuration_.global_configuration.num_residual_layers == 4) {
00506         // 2x2 case
00507         d1 = default_qm_coefficient_2x2[2]; // LOQ1
00508         // 4x4 case
00509         if (horizontal_only)
00510             d2 = default_qm_coefficient_2x2[0]; // LOQ2 1D
00511         else
00512             d2 = default_qm_coefficient_2x2[1]; // LOQ2 2D
00513     } else {
00514         // 4x4 case
00515         d1 = default_qm_coefficient_4x4[2]; // LOQ1
00516         if (horizontal_only)
00517             d2 = default_qm_coefficient_4x4[0]; // LOQ2 1D
00518         else
00519             d2 = default_qm_coefficient_4x4[1]; // LOQ2 2D
00520     }
00521     for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00522         configuration_.picture_configuration.qm_coefficient_2[i] = d2[i];
00523         configuration_.picture_configuration.qm_coefficient_1[i] = d1[i];
00524     }
00525 
00526     if (configuration_.picture_configuration.coding_type != CodingType_IDR ||
00527         configuration_.picture_configuration.enhancement_enabled) {
00528         // if it is not IDR or enhancement_enabled is true, use the quant_matrix_mode value for the QM choice
00529         // second, set the QM to specific custom values
00530         if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_BothPrevious) {
00531             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00532                 configuration_.picture_configuration.qm_coefficient_2[i] =
00533                     configuration_.picture_configuration.qm_coefficient_2_mem[i];
00534                 configuration_.picture_configuration.qm_coefficient_1[i] =
00535                     configuration_.picture_configuration.qm_coefficient_1_mem[i];
00536             }
00537         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_BothDefault) {
00538             const uint8_t *d2 = nullptr;
00539             const uint8_t *d1 = nullptr;
00540             const bool horizontal_only =
00541                 (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_2] == ScalingMode_1D ? true : false);
00542             if (configuration_.global_configuration.num_residual_layers == 4) {
00543                 // 2x2 case
00544                 d1 = default_qm_coefficient_2x2[2]; // LOQ1
00545                 // 4x4 case
00546                 if (horizontal_only)
00547                     d2 = default_qm_coefficient_2x2[0]; // LOQ2 1D
00548                 else
00549                     d2 = default_qm_coefficient_2x2[1]; // LOQ2 2D
00550             } else {
00551                 // 4x4 case
00552                 d1 = default_qm_coefficient_4x4[2]; // LOQ1
00553                 if (horizontal_only)
00554                     d2 = default_qm_coefficient_4x4[0]; // LOQ2 1D
00555                 else
00556                     d2 = default_qm_coefficient_4x4[1]; // LOQ2 2D
00557             }
00558             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00559                 configuration_.picture_configuration.qm_coefficient_2[i] = d2[i];
00560                 configuration_.picture_configuration.qm_coefficient_1[i] = d1[i];
00561             }
00562         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_SameAndCustom) {
00563             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00564                 configuration_.picture_configuration.qm_coefficient_2[i] =
00565                     configuration_.picture_configuration.qm_coefficient_2_par[i];
00566                 configuration_.picture_configuration.qm_coefficient_1[i] = configuration_.picture_configuration.qm_coefficient_2[i];
00567             }
00568         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_Level2CustomLevel1Default) {
00569             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00570                 configuration_.picture_configuration.qm_coefficient_2[i] =
00571                     configuration_.picture_configuration.qm_coefficient_2_par[i];
00572                 configuration_.picture_configuration.qm_coefficient_1[i] =
00573                     configuration_.picture_configuration.qm_coefficient_1_mem[i];
00574             }
00575         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_Level2DefaultLevel1Custom) {
00576             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00577                 configuration_.picture_configuration.qm_coefficient_2[i] =
00578                     configuration_.picture_configuration.qm_coefficient_2_mem[i];
00579                 configuration_.picture_configuration.qm_coefficient_1[i] =
00580                     configuration_.picture_configuration.qm_coefficient_1_par[i];
00581             }
00582         } else if (configuration_.picture_configuration.quant_matrix_mode == QuantMatrix_DifferentAndCustom) {
00583             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00584                 configuration_.picture_configuration.qm_coefficient_2[i] =
00585                     configuration_.picture_configuration.qm_coefficient_2_par[i];
00586                 configuration_.picture_configuration.qm_coefficient_1[i] =
00587                     configuration_.picture_configuration.qm_coefficient_1_par[i];
00588             }
00589         }
00590     }
00591     // else -- if it is IDR and enhancement_enabled is false, reset to QM default // nothing to do: keep the QM default
00592 
00593     // third, save the QM in memory for the next round
00594     for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00595         configuration_.picture_configuration.qm_coefficient_2_mem[i] = configuration_.picture_configuration.qm_coefficient_2[i];
00596         configuration_.picture_configuration.qm_coefficient_1_mem[i] = configuration_.picture_configuration.qm_coefficient_1[i];
00597     }
00598     configuration_.picture_configuration.temporal_signalling_present = false;
00599 }
