00601 // Does this layer have user_data embedded?
00602 //
00603 bool Encoder::is_user_data_layer(unsigned loq, unsigned layer) const {
00604     if (loq == LOQ_LEVEL_1 && configuration_.global_configuration.user_data_enabled != UserData_None) {
00605         if (configuration_.global_configuration.transform_block_size == 4)
00606             return layer == 5;
00607         else
00608             return layer == 1;
00609     }
00610     // No embedded user data
00611     return false;
00612 }
00613 
00614 void Encoder::encode_residuals(unsigned plane, unsigned loq, const Surface &residuals, Surface symbols[MAX_NUM_LAYERS],
00615                                Temporal_SWM swm_type, EncodingMode mode, const Surface &temporal_mask, const Surface &priority_type,
00616                                PriorityMBType priority_mb_type, const bool final, const Surface &pixel_sad) const {
00618     //
00619     Surface coefficients[MAX_NUM_LAYERS];
00620     const bool horizontal_only = (configuration_.global_configuration.scaling_mode[loq] == ScalingMode_1D ? true : false);
00621 
00622     if (!horizontal_only) {
00623         // Horizontal and Vertical
00624         //
00625         if (configuration_.global_configuration.transform_block_size == 4) {
00626             TransformDDS().process(residuals, EncodingMode::ENCODE_ALL, coefficients);
00627         } else if (configuration_.global_configuration.transform_block_size == 2) {
00628             TransformDD().process(residuals, EncodingMode::ENCODE_ALL, coefficients);
00629         }
00630     } else {
00631         // Horizontal only
00632         //
00633         if (configuration_.global_configuration.transform_block_size == 4) {
00634             TransformDDS_1D().process(residuals, EncodingMode::ENCODE_ALL, coefficients);
00635         } else if (configuration_.global_configuration.transform_block_size == 2) {
00636             TransformDD_1D().process(residuals, EncodingMode::ENCODE_ALL, coefficients);
00637         }
00638     }
00639 
00640     if (final && loq == LOQ_LEVEL_1)
00641         Surface::dump_layers(coefficients, format("enc_base_coeff_transform_output_P%1d", plane), transform_block_size());
00642     else if (final && loq == LOQ_LEVEL_2)
00643         Surface::dump_layers(coefficients, format("enc_full_coeff_transform_output_P%1d", plane), transform_block_size());
00644 
00645     Surface coefficients_sad[MAX_NUM_LAYERS];
00646     if (!pixel_sad.empty() && encoder_configuration_.sad_threshold != 0 && encoder_configuration_.sad_coeff_threshold != 0) {
00647         StaticResiduals().process(coefficients, coefficients_sad, pixel_sad, num_residual_layers(),
00648                                   configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2],
00649                                   encoder_configuration_.sad_threshold, encoder_configuration_.sad_coeff_threshold);
00650         if (final && loq == LOQ_LEVEL_2)
00651             Surface::dump_layers(coefficients_sad, format("enc_full_coeff_SAD_output_P%1d", plane), transform_block_size());
00652     } else {
00653         for (unsigned layer = 0; layer < num_residual_layers(); layer++) {
00654             const auto coeff = coefficients[layer].view_as<int16_t>();
00655             coefficients_sad[layer] = Surface::build_from<int16_t>()
00656                                           .generate(coefficients[layer].width(), coefficients[layer].height(),
00657                                                     [&](unsigned x, unsigned y) -> int16_t { return coeff.read(x, y); })
00658                                           .finish();
00659         }
00660     }
00661 
00662 #if defined PRIORITY_COEF
00663     Surface priority_coefficients[MAX_NUM_LAYERS];
00664     if (priority_type.width() != 0 && priority_type.height() != 0) {
00665         PriorityMap().ApplyPriorityCoefficients(coefficients_sad[0].width(), coefficients_sad[0].height(),
00666                                                 configuration_.global_configuration.transform_block_size, loq, coefficients_sad,
00667                                                 priority_coefficients, priority_type, pixel_sad,
00668                                                 configuration_.picture_configuration.step_width_loq[loq], priority_mb_type, mode);
00669         if (final && loq == LOQ_LEVEL_1)
00670             Surface::dump_layers(priority_coefficients, format("enc_base_coeff_PM_output_P%1d", plane), transform_block_size());
00671         else if (final && loq == LOQ_LEVEL_2)
00672             Surface::dump_layers(priority_coefficients, format("enc_full_coeff_PM_output_P%1d", plane), transform_block_size());
00673     } else {
00674         for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00675             const auto coef = coefficients_sad[i].view_as<int16_t>();
00676             priority_coefficients[i] = Surface::build_from<int16_t>()
00677                                            .generate(coefficients_sad[i].width(), coefficients_sad[i].height(),
00678                                                      [&](unsigned x, unsigned y) -> int16_t { return coef.read(x, y); })
00679                                            .finish();
00680         }
00681     }
00682 #endif // defined PRIORITY_COEF
00683 
00685     //
00686     int32_t dirq_step_width[MAX_NUM_LAYERS][2] = {};
00687     int32_t dirq_deadzone[MAX_NUM_LAYERS][2] = {};
00688     unsigned passes = 1;
00689 
00690     {
00691         // XXX This looks to be replicated twice here and once in the decoder
00692         unsigned step_width[2];
00693         int16_t calculated_step_width = configuration_.picture_configuration.step_width_loq[loq];
00694         if (loq == LOQ_LEVEL_2 && plane > 0) {
00695             calculated_step_width =
00696                 clamp((int16_t)((calculated_step_width * configuration_.global_configuration.chroma_step_width_multiplier) >> 6),
00697                       (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00698         }
00699         if (loq == LOQ_LEVEL_2) {
00700             switch (swm_type) {
00701             case Temporal_SWM::SWM_Disabled:
00702                 step_width[0] = calculated_step_width;
00703                 break;
00704             case Temporal_SWM::SWM_Active:
00705                 step_width[0] =
00706                     clamp((int16_t)(calculated_step_width *
00707                                     (1 - clamp(((float)configuration_.global_configuration.temporal_step_width_modifier / (float)255),
00708                                                (float)0, (float)0.5))),
00709                           (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00710                 break;
00711             case Temporal_SWM::SWM_Dependent:
00712                 step_width[0] =
00713                     clamp((int16_t)(calculated_step_width *
00714                                     (1 - clamp(((float)configuration_.global_configuration.temporal_step_width_modifier / (float)255),
00715                                                (float)0, (float)0.5))),
00716                           (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00717                 step_width[1] = calculated_step_width;
00718                 passes = 2;
00719                 break;
00720             default:
00721                 CHECK(0);
00722                 break;
00723             }
00724         } else
00725             step_width[0] = calculated_step_width;
00726 
00727         for (unsigned pass = 0; pass < passes; pass++) {
00728             for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00729                 dirq_step_width[layer][pass] = find_dirq_step_width(step_width[pass], quant_matrix_coeffs_[plane][loq][layer]);
00730                 dirq_deadzone[layer][pass] = find_layer_deadzone(step_width[pass], dirq_step_width[layer][pass]);
00731             }
00732         }
00733     }
00734 
00736     //
00737     for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00738 
00739         Surface syms;
00740         if (passes == 1) {
00741 #if defined PRIORITY_COEF
00742             syms = Quantize().process(priority_coefficients[layer], dirq_step_width[layer][0], dirq_deadzone[layer][0], pixel_sad,
00743                                       transform_block_size(), encoder_configuration_.quant_reduced_deadzone);
00744 #else  // defined PRIORITY_COEF
00745             syms = Quantize().process(coefficients_sad[layer], dirq_step_width[layer][0], dirq_deadzone[layer][0], pixel_sad,
00746                                       transform_block_size(), encoder_configuration_.quant_reduced_deadzone);
00747 #endif // defined PRIORITY_COEF
00748         } else {
00749 #if defined PRIORITY_COEF
00750             syms = Quantize_SWM().process(priority_coefficients[layer], transform_block_size(), dirq_step_width[layer],
00751                                           dirq_deadzone[layer], temporal_mask, pixel_sad,
00752                                           encoder_configuration_.quant_reduced_deadzone);
00753 #else  // defined PRIORITY_COEF
00754             syms = Quantize_SWM().process(coefficients_sad[layer], transform_block_size(), dirq_step_width[layer],
00755                                           dirq_deadzone[layer], temporal_mask, pixel_sad,
00756                                           encoder_configuration_.quant_reduced_deadzone);
00757 #endif // defined PRIORITY_COEF
00758         }
00759         if (is_user_data_layer(loq, layer)) {
00761 #if USER_DATA_EXTRACTION
00762             FILE *file = fopen("userdata_enc.bin", "ab");
00763             symbols[layer] = UserDataInsert().process(syms, encoder_configuration_.user_data_method,
00764                                                       configuration_.global_configuration.user_data_enabled, file);
00765             fclose(file);
00766 #else
00767             symbols[layer] = UserDataInsert().process(syms, encoder_configuration_.user_data_method,
00768                                                       configuration_.global_configuration.user_data_enabled);
00769 #endif
00770         } else
00771             symbols[layer] = syms;
00772     }
00773     if (final && loq == LOQ_LEVEL_1)
00774         Surface::dump_layers(symbols, format("enc_base_coeff_quant_output_P%1d", plane), transform_block_size());
00775     else if (final && loq == LOQ_LEVEL_2)
00776         Surface::dump_layers(symbols, format("enc_full_coeff_quant_output_P%1d", plane), transform_block_size());
00777 
00778     if (final && !pixel_sad.empty() && pixel_sad.get_dump_surfaces() && loq == LOQ_LEVEL_2) {
00779         // Creation of debug maps
00780 
00781         Surface priority_debug[MAX_NUM_LAYERS];
00782         if (priority_type.width() != 0 && priority_type.height() != 0) {
00783             PriorityMap().ApplyPriorityCoefficients(
00784                 coefficients[0].width(), coefficients[0].height(), configuration_.global_configuration.transform_block_size, loq,
00785                 coefficients, priority_debug, priority_type, pixel_sad, configuration_.picture_configuration.step_width_loq[loq],
00786                 priority_mb_type, mode);
00787         } else {
00788             for (unsigned i = 0; i < configuration_.global_configuration.num_residual_layers; i++) {
00789                 const auto coef = coefficients[i].view_as<int16_t>();
00790                 priority_debug[i] = Surface::build_from<int16_t>()
00791                                         .generate(coefficients[i].width(), coefficients[i].height(),
00792                                                   [&](unsigned x, unsigned y) -> int16_t { return coef.read(x, y); })
00793                                         .finish();
00794             }
00795         }
00796 
00797         Surface syms_anchor[MAX_NUM_LAYERS], syms_no_sad[MAX_NUM_LAYERS];
00798 
00799         for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00800             Surface syms_a, syms_b;
00801             if (passes == 1) {
00802                 syms_a = Quantize().process(priority_coefficients[layer], dirq_step_width[layer][0], dirq_deadzone[layer][0],
00803                                             pixel_sad, transform_block_size(), 5u);
00804                 syms_b = Quantize().process(priority_debug[layer], dirq_step_width[layer][0], dirq_deadzone[layer][0], pixel_sad,
00805                                             transform_block_size(), 5u);
00806             } else {
00807                 syms_a = Quantize_SWM().process(priority_coefficients[layer], transform_block_size(), dirq_step_width[layer],
00808                                                 dirq_deadzone[layer], temporal_mask, pixel_sad, 5u);
00809                 syms_b = Quantize_SWM().process(priority_debug[layer], transform_block_size(), dirq_step_width[layer],
00810                                                 dirq_deadzone[layer], temporal_mask, pixel_sad, 5u);
00811             }
00812             syms_anchor[layer] = syms_a;
00813             syms_no_sad[layer] = syms_b;
00814         }
00815 
00816         const Surface static_residuals_debug =
00817             Surface::build_from<int16_t>()
00818                 .generate(residuals.width(), residuals.height(),
00819                           [&](unsigned x, unsigned y) -> int16_t {
00820                               const unsigned layer =
00821                                   (x % transform_block_size() + transform_block_size() * (y % transform_block_size()));
00822                               const auto syms_anchor_view = syms_anchor[layer].view_as<int16_t>();
00823                               const auto syms_view = symbols[layer].view_as<int16_t>();
00824                               const auto syms_no_sad_view = syms_no_sad[layer].view_as<int16_t>();
00825 
00826                               if (syms_no_sad_view.read(x / transform_block_size(), y / transform_block_size()) !=
00827                                   syms_anchor_view.read(x / transform_block_size(), y / transform_block_size()))
00828                                   return 20000;
00829                               else if (syms_anchor_view.read(x / transform_block_size(), y / transform_block_size()) !=
00830                                        syms_view.read(x / transform_block_size(), y / transform_block_size()))
00831                                   return -20000;
00832                               else
00833                                   return 0;
00834                           })
00835                 .finish();
00836         static_residuals_debug.dump(format("enc_full_coeff_SAD_changes_P%1d", plane));
00837     }
00838 }
00839 
00840 Surface Encoder::decode_residuals(unsigned plane, unsigned loq, const Surface symbols[MAX_NUM_LAYERS], Temporal_SWM temp_type,
00841                                   const Surface &temporal_mask) const {
00842 
00843     Surface coefficients[MAX_NUM_LAYERS] = {};
00844     int32_t dirq_step_width[MAX_NUM_LAYERS][2] = {};
00845     int32_t invq_step_width[MAX_NUM_LAYERS][2] = {};
00846     int32_t invq_offset[MAX_NUM_LAYERS][2] = {};
00847     int32_t invq_deadzone[MAX_NUM_LAYERS][2] = {};
00848     const bool horizontal_only = (configuration_.global_configuration.scaling_mode[loq] == ScalingMode_1D ? true : false);
00849 
00850     // Apply temporal step width modifier, if required
00851     unsigned passes = 1;
00852     {
00853         int16_t step_width[2];
00854         int16_t calculated_step_width = configuration_.picture_configuration.step_width_loq[loq];
00855         if (loq == LOQ_LEVEL_2 && plane > 0) {
00856             calculated_step_width =
00857                 clamp((int16_t)((calculated_step_width * configuration_.global_configuration.chroma_step_width_multiplier) >> 6),
00858                       (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00859         }
00860         if (loq == LOQ_LEVEL_2) {
00861             switch (temp_type) {
00862             case Temporal_SWM::SWM_Disabled:
00863                 step_width[0] = calculated_step_width;
00864                 break;
00865             case Temporal_SWM::SWM_Active:
00866                 step_width[0] =
00867                     clamp((int16_t)(calculated_step_width *
00868                                     (1 - clamp(((float)configuration_.global_configuration.temporal_step_width_modifier / (float)255),
00869                                                (float)0, (float)0.5))),
00870                           (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00871                 break;
00872             case Temporal_SWM::SWM_Dependent:
00873                 step_width[0] =
00874                     clamp((int16_t)(calculated_step_width *
00875                                     (1 - clamp(((float)configuration_.global_configuration.temporal_step_width_modifier / (float)255),
00876                                                (float)0, (float)0.5))),
00877                           (int16_t)MIN_STEP_WIDTH, (int16_t)MAX_STEP_WIDTH);
00878                 step_width[1] = calculated_step_width;
00879                 passes = 2;
00880                 break;
00881             default:
00882                 break;
00883             }
00884         } else {
00885             step_width[0] = calculated_step_width;
00886         }
00887 
00888         for (unsigned pass = 0; pass < passes; pass++) {
00889             for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00890                 dirq_step_width[layer][pass] = find_dirq_step_width(step_width[pass], quant_matrix_coeffs_[plane][loq][layer]);
00891                 invq_offset[layer][pass] =
00892                     find_invq_offset(configuration_.picture_configuration, step_width[pass], dirq_step_width[layer][pass]);
00893 
00894                 invq_step_width[layer][pass] =
00895                     find_invq_step_width(configuration_.picture_configuration, dirq_step_width[layer][pass], invq_offset[layer][pass]);
00896 
00897                 invq_deadzone[layer][pass] = find_layer_deadzone(step_width[pass], invq_step_width[layer][pass]);
00898             }
00899         }
00900     }
00901 
00902     // Dequantize
00903     for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
00904         Surface syms;
00905         if (is_user_data_layer(loq, layer))
00906             syms = UserDataClear().process(symbols[layer], configuration_.global_configuration.user_data_enabled);
00907         else
00908             syms = symbols[layer];
00909 
00910         if (passes == 1) {
00911             coefficients[layer] = InverseQuantize().process(
00912                 syms, invq_step_width[layer][0],
00913                 find_invq_applied_offset(configuration_.picture_configuration, invq_offset[layer][0], invq_deadzone[layer][0]));
00914         } else {
00915             int32_t invq_applied_offset[2] = {
00916                 find_invq_applied_offset(configuration_.picture_configuration, invq_offset[layer][0], invq_deadzone[layer][0]),
00917                 find_invq_applied_offset(configuration_.picture_configuration, invq_offset[layer][1], invq_deadzone[layer][1])};
00918 
00919             coefficients[layer] = InverseQuantize_SWM().process(symbols[layer], transform_block_size(), invq_step_width[layer],
00920                                                                 invq_applied_offset, temporal_mask);
00921         }
00922     }
00923 
00924     Surface residuals;
00925 
00926     if (!horizontal_only) {
00927         // Inverse Transform Horizontal and Vertical
00928         //
00929         if (configuration_.global_configuration.transform_block_size == 4)
00930             residuals = InverseTransformDDS().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00931                                                       coefficients);
00932         else if (configuration_.global_configuration.transform_block_size == 2)
00933             residuals = InverseTransformDD().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00934                                                      coefficients);
00935     } else {
00936         // Inverse Transform Horizontal only
00937         //
00938         if (configuration_.global_configuration.transform_block_size == 4)
00939             residuals = InverseTransformDDS_1D().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00940                                                          coefficients);
00941         else if (configuration_.global_configuration.transform_block_size == 2)
00942             residuals = InverseTransformDD_1D().process(dimensions_.plane_width(plane, loq), dimensions_.plane_height(plane, loq),
00943                                                         coefficients);
00944     }
00945 
00946     return residuals;
00947 }
00948 
00949 // Decide what syntax blocks should be serialized
00950 //
00951 static unsigned syntax_blocks_mask(BaseFrameType frame_type, bool encoded_data_present, bool tiled, bool additional_info_present) {
00952     SyntaxBlocks data{};
00953 
00954     if (encoded_data_present)
00955         data = tiled ? SyntaxBlock_EncodedData : SyntaxBlock_EncodedData_Tiled;
00956 
00957     switch (frame_type) {
00958     case BaseFrame_IDR:
00959     case BaseFrame_Intra:
00960         if (additional_info_present)
00961             return SyntaxBlock_Global | SyntaxBlock_Picture | SyntaxBlock_Sequence | SyntaxBlock_Additional_Info | data;
00962         else
00963             return SyntaxBlock_Global | SyntaxBlock_Picture | SyntaxBlock_Sequence | data;
00964 
00965     case BaseFrame_Inter:
00966     case BaseFrame_Pred:
00967     case BaseFrame_Bidi:
00968         return SyntaxBlock_Picture | data;
00969     }
00970 
00971     return 0;
00972 }
