00984 // Encode one enhancement frame, given source image, downsampled source, and the decoded base image
00985 //
00986 Packet Encoder::encode(std::vector<std::unique_ptr<Image>> &src_image, const Image &intermediate_src_image,
00987                        const Image &base_prediction_image, BaseFrameType frame_type, bool is_idr, int gop_frame_num,
00988                        const std::string &output_file) {
00989 
00990     if (dithering_.getInitialised() == false) {
00991         INFO("Dither init %4d bitdepth %d", configuration_.picture_configuration.dithering_strength,
00992              configuration_.global_configuration.enhancement_depth);
00993         dithering_.make_buffer(configuration_.picture_configuration.dithering_strength,
00994                                configuration_.global_configuration.enhancement_depth,
00995                                configuration_.picture_configuration.dithering_type == Dithering_UniformFixed ? true : false);
00996         dithering_.setInitialised(true);
00997     }
00998 
00999     Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS];
01000 
01001     unsigned frame = (unsigned)(intermediate_src_image.timestamp());
01002 
01003     // Figure out whether data should be sent
01004     if (configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_1] >= MAX_STEP_WIDTH &&
01005         configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] >= MAX_STEP_WIDTH) {
01006         if (!configuration_.global_configuration.temporal_enabled)
01007             configuration_.picture_configuration.enhancement_enabled = false;
01008         else {
01009             if ((frame_type == BaseFrame_Intra || frame_type == BaseFrame_IDR) &&
01010                 encoder_configuration_.temporal_cq_sw_multiplier != 1000)
01011                 configuration_.picture_configuration.enhancement_enabled = true;
01012             else
01013                 configuration_.picture_configuration.enhancement_enabled = false;
01014         }
01015     } else
01016         configuration_.picture_configuration.enhancement_enabled = true;
01017 
01018     if (frame_type == BaseFrame_Intra || frame_type == BaseFrame_IDR) {
01019         configuration_.picture_configuration.coding_type = CodingType_IDR;
01020         update_picture_configuration_in_loop();
01021     } else {
01022         configuration_.picture_configuration.coding_type = CodingType_NonIDR;
01023         update_picture_configuration_in_loop();
01024     }
01025 
01026     // For each plane
01027     //
01028     Surface base_reco[MAX_NUM_PLANES];
01029     Surface full_reco[MAX_NUM_PLANES];
01030     Surface outp_reco[MAX_NUM_PLANES];
01031 
01032     // Needed to randomly generate user data (part of CE)
01033     if (configuration_.global_configuration.user_data_enabled) {
01034         if (encoder_configuration_.user_data_method == UserDataMethod_Random)
01035             Random().srand((unsigned)std::time(nullptr));
01036         else if (encoder_configuration_.user_data_method == UserDataMethod_FixedRandom)
01037             Random().srand(45721);
01038     }
01039 
01040     configuration_.picture_configuration.temporal_refresh = false;
01041 
01042     for (unsigned plane = 0; plane < src_image[0]->description().num_planes(); ++plane) {
01043         const bool enhancement_enabled = configuration_.picture_configuration.enhancement_enabled &&
01044                                          plane < configuration_.global_configuration.num_processed_planes;
01045 
01047         Surface base_image;
01048         unsigned base_bit_depth = configuration_.global_configuration.base_depth;
01049         if (configuration_.global_configuration.enhancement_depth > configuration_.global_configuration.base_depth &&
01050             configuration_.global_configuration.level1_depth_flag) {
01051             base_image =
01052                 ConvertBitShift().process(base_prediction_image.plane(plane), configuration_.global_configuration.base_depth,
01053                                           configuration_.global_configuration.enhancement_depth);
01054             base_bit_depth = configuration_.global_configuration.enhancement_depth;
01055         } else {
01056             base_image = base_prediction_image.plane(plane);
01057         }
01058 
01059         const Surface src = ConvertToInternal().process(src_image[0]->plane(plane), src_image[0]->description().bit_depth());
01060         const Surface intermediate_src =
01061             ConvertToInternal().process(intermediate_src_image.plane(plane), intermediate_src_image.description().bit_depth());
01062         const Surface base_decoded = ConvertToInternal().process(base_image, base_bit_depth);
01063         Surface temporal_mask;
01064 
01065         // Work out quantization matrix for each LoQ
01066         for (unsigned loq = 0l; loq < MAX_NUM_LOQS; ++loq) {
01067             const bool horizontal_only = (configuration_.global_configuration.scaling_mode[loq] == ScalingMode_1D ? true : false);
01068             for (unsigned layer = 0; layer < num_residual_layers(); ++layer) {
01069                 quant_matrix_coeffs_[plane][loq][layer] =
01070                     find_quant_matrix_coeff(configuration_.picture_configuration, num_residual_layers(), horizontal_only, loq,
01071                                             layer, is_idr, quant_matrix_coeffs_[plane][loq][layer]);
01072             }
01073         }
01074 
01078 
01080         //
01081         Surface base_prediction;
01082         switch (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_1]) {
01083         case ScalingMode_1D:
01084             base_prediction = Upsampling_1D().process(base_decoded, configuration_.global_configuration.upsample,
01085                                                       configuration_.global_configuration.upsampling_coefficients);
01086             if (configuration_.global_configuration.predicted_residual_enabled) {
01087                 base_prediction = PredictedResidualAdjust_1D().process(base_decoded, base_prediction,
01088                                                                        PredictedResidualSum_1D().process(base_prediction));
01089             }
01090             base_decoded.dump(format("enc_base_deco_P%1d", plane));
01091             break;
01092         case ScalingMode_2D:
01093             base_prediction = Upsampling().process(base_decoded, configuration_.global_configuration.upsample,
01094                                                    configuration_.global_configuration.upsampling_coefficients);
01095             if (configuration_.global_configuration.predicted_residual_enabled) {
01096                 base_prediction = PredictedResidualAdjust().process(base_decoded, base_prediction,
01097                                                                     PredictedResidualSum().process(base_prediction));
01098             }
01099             base_decoded.dump(format("enc_base_deco_P%1d", plane));
01100             break;
01101         case ScalingMode_None:
01102             base_prediction = base_decoded;
01103             break;
01104         default:
01105             CHECK(0);
01106         }
01107 
01108         base_prediction.dump(format("enc_base_pred_P%1d", plane));
01109 
01113 
01114         if (enhancement_enabled) {
01115             // Enhancement
01116             Surface base_residuals = Subtract().process(intermediate_src, base_prediction);
01117 
01118             base_residuals.dump(format("enc_base_resi_inpu_P%1d", plane));
01119 
01120             // Apply residual map
01121             if (encoder_configuration_.temporal_use_priority_map_sl_1 &&
01122                 (encoder_configuration_.encoding_mode != EncodingMode::ENCODE_NONE) && (plane == 0)) {
01123                 // std::cout << "==> ENCODER::Going to use priority map" << std::endl;
01124 #if defined PRIORITY_TEST
01125                 const unsigned priority_tile_x = 8u;
01126                 const unsigned priority_tile_y = 8u;
01127                 const auto priority_map_loq1 = PriorityMap().process(intermediate_src_image.plane(0), priority_tile_x,
01128                                                                      priority_tile_y, KillingFunction::THRESHOLD_CUTOFF);
01129 
01130                 Surface selected_base_residuals = ApplyPreprocessedMap().process(base_residuals, priority_map_loq1);
01131 
01132                 encode_residuals(plane, LOQ_LEVEL_1, selected_base_residuals, symbols[plane][LOQ_LEVEL_1],
01133                                  Temporal_SWM::SWM_Disabled, encoder_configuration_.encoding_mode, Surface(), Surface(),
01134                                  encoder_configuration_.priority_type_sl_1);
01135 
01136                 constexpr bool record_priority_map = false;
01137                 if (record_priority_map) {
01138                     // Dump priority map to file
01139                     const auto priority_map_loq1_vis = PriorityMapVis().process(priority_map_loq1);
01140 
01141                     const auto surface_dump_flag = Surface::get_dump_surfaces();
01142                     Surface::set_dump_surfaces(true);
01143                     priority_map_loq1_vis.dump(format("recorded_priority_map"));
01144                     Surface::set_dump_surfaces(surface_dump_flag);
01145                 }
01146 #endif // defined PRIORITY_TEST
01147 #if defined PRIORITY_RESI_SL1 || defined PRIORITY_COEF
01148                 Surface priority_mean = PriorityMap().ComputeMeanValue(intermediate_src);
01149                 Surface priority_type = PriorityMap().ComputeContrastTexture(intermediate_src, priority_mean);
01150                 priority_type.dump(format("priority_map_layer1"));
01151 #endif // defined PRIORITY_RESI || defined PRIORITY_COEF
01152 
01153 #if defined PRIORITY_RESI_SL1 // NEED REVISITATION FOR SL-1 TO INCLUDE ADDITIONAL PM TYPE AND MODE
01154                 Surface priority_residuals = PriorityMap().ApplyPriorityResiduals(
01155                     base_residuals, priority_type, configuration_.picture_configuration.step_width_loq[1]);
01156                 encode_residuals(plane, LOQ_LEVEL_1, priority_residuals, symbols[plane][LOQ_LEVEL_1], Temporal_SWM::SWM_Disabled,
01157                                  encoder_configuration_.encoding_mode, Surface(), Surface(),
01158                                  encoder_configuration_.priority_type_sl_1, true);
01159 #endif // defined PRIORITY_RESI
01160 #if defined PRIORITY_COEF
01161                 encode_residuals(plane, LOQ_LEVEL_1, base_residuals, symbols[plane][LOQ_LEVEL_1], Temporal_SWM::SWM_Disabled,
01162                                  encoder_configuration_.encoding_mode, Surface(), priority_type,
01163                                  encoder_configuration_.priority_type_sl_1, true);
01164 #endif        // defined PRIORITY_COEF
01165             } // if plane == 0
01166             else {
01167                 encode_residuals(plane, LOQ_LEVEL_1, base_residuals, symbols[plane][LOQ_LEVEL_1], Temporal_SWM::SWM_Disabled,
01168                                  EncodingMode::ENCODE_ALL, Surface(), Surface(), encoder_configuration_.priority_type_sl_1, true);
01169             }
01170 
01171             // Reconstruct base
01172             //
01173             Surface base_residuals_recon =
01174                 decode_residuals(plane, LOQ_LEVEL_1, symbols[plane][LOQ_LEVEL_1], Temporal_SWM::SWM_Disabled, Surface());
01175 
01176             base_residuals_recon.dump(format("enc_base_resi_reco_P%1d", plane));
01177 
01178             // Deblocking
01179             if (configuration_.picture_configuration.level_1_filtering_enabled &&
01180                 configuration_.global_configuration.transform_block_size == 4) {
01181                 base_residuals_recon = Deblocking().process(
01182                     base_residuals_recon, configuration_.global_configuration.level_1_filtering_first_coefficient,
01183                     configuration_.global_configuration.level_1_filtering_second_coefficient);
01184             }
01185 
01186             base_reco[plane] = Add().process(base_prediction, base_residuals_recon);
01187 
01188         } else {
01189             // No enhancement, Just pass prediction through
01190             base_reco[plane] = base_prediction;
01191         }
01192 
01194         //
01195         Surface enhanced_prediction;
01196         switch (configuration_.global_configuration.scaling_mode[LOQ_LEVEL_2]) {
01197         case ScalingMode_1D:
01198             enhanced_prediction = Upsampling_1D().process(base_reco[plane], configuration_.global_configuration.upsample,
01199                                                           configuration_.global_configuration.upsampling_coefficients);
01200             if (configuration_.global_configuration.predicted_residual_enabled) {
01201                 enhanced_prediction = PredictedResidualAdjust_1D().process(base_reco[plane], enhanced_prediction,
01202                                                                            PredictedResidualSum_1D().process(enhanced_prediction));
01203             }
01204             break;
01205         case ScalingMode_2D:
01206             enhanced_prediction = Upsampling().process(base_reco[plane], configuration_.global_configuration.upsample,
01207                                                        configuration_.global_configuration.upsampling_coefficients);
01208             if (configuration_.global_configuration.predicted_residual_enabled) {
01209                 enhanced_prediction = PredictedResidualAdjust().process(base_reco[plane], enhanced_prediction,
01210                                                                         PredictedResidualSum().process(enhanced_prediction));
01211             }
01212             break;
01213         case ScalingMode_None:
01214             enhanced_prediction = base_reco[plane];
01215             break;
01216         default:
01217             CHECK(0);
01218         }
01219 
01220         enhanced_prediction.dump(format("enc_full_pred_P%1d", plane));
01221 
01225 
01226         if (enhancement_enabled) {
01227             /* const */ Surface enhanced_residuals = Subtract().process(src, enhanced_prediction);
01228             Surface temporal_mask_per_transform;
01229             Surface temporal_tile_map;
01230 
01231             const Surface src_next =
01232                 (src_image.size() > 1 && plane == 0 &&
01233                  ((encoder_configuration_.sad_threshold != 0 && encoder_configuration_.sad_coeff_threshold != 0) ||
01234                   (encoder_configuration_.temporal_use_priority_map_sl_2 &&
01235                    encoder_configuration_.encoding_mode != EncodingMode::ENCODE_NONE) ||
01236                   encoder_configuration_.quant_reduced_deadzone != 5))
01237                     ? ConvertToInternal().process(src_image[1]->plane(plane), src_image[1]->description().bit_depth())
01238                     : Surface();
01239             const Surface pixel_sad =
01240                 !src_next.empty()
01241                     ? TemporalCost_SAD().process(src, src_next, configuration_.global_configuration.transform_block_size)
01242                     : Surface();
01243             if (!pixel_sad.empty() && pixel_sad.get_dump_surfaces()) {
01244                 pixel_sad.dump(format("enc_pixel_sad_P%1d", plane));
01245 
01246                 // Dump pixel SAD map highlighting static and non-static areas
01247                 const auto pixel_sad_view = pixel_sad.view_as<int16_t>();
01248                 const Surface static_areas_map = Surface::build_from<int16_t>()
01249                                                      .generate(pixel_sad_view.width(), pixel_sad_view.height(),
01250                                                                [&](unsigned x, unsigned y) -> int16_t {
01251                                                                    const int16_t src = pixel_sad_view.read(x, y);
01252                                                                    if (src <= (transform_block_size() == 4 ? 200 : 100))
01253                                                                        return -20000;
01254                                                                    else if (src <= (transform_block_size() == 4 ? 12000 : 6000))
01255                                                                        return 0;
01256                                                                    else
01257                                                                        return 20000;
01258                                                                })
01259                                                      .finish();
01260                 static_areas_map.dump(format("enc_static_areas_map_P%1d", plane));
01261             }
01262 
01263             if (!configuration_.picture_configuration.temporal_signalling_present &&
01264                 (!configuration_.global_configuration.temporal_enabled || previous_residuals_[plane].empty() ||
01265                  frame_type == BaseFrame_Intra || frame_type == BaseFrame_IDR)) {
01267                 //
01268                 configuration_.picture_configuration.temporal_refresh = true;
01269                 configuration_.picture_configuration.temporal_signalling_present = false;
01270 
01271                 if (frame_type == BaseFrame_IDR || frame_type == BaseFrame_Intra)
01272                     last_idr_frame_num = gop_frame_num;
01273                 if ((frame_type == BaseFrame_IDR || frame_type == BaseFrame_Intra) &&
01274                     configuration_.global_configuration.temporal_enabled) {
01275                     configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] =
01276                         clamp(configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2] *
01277                                   encoder_configuration_.temporal_cq_sw_multiplier / 1000,
01278                               (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
01279                 } else {
01280                     configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] =
01281                         (configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2]);
01282                 }
01283 
01284 #if defined DELTA_SW
01285                 if (!(frame_type == BaseFrame_Intra || frame_type == BaseFrame_IDR)) {
01286                     if ((gop_frame_num - last_idr_frame_num) % 8 == 0) {
01287                         configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] =
01288                             clamp(configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2] *
01289                                       encoder_configuration_.delta_sw_mult_gop08 / 1000,
01290                                   (unsigned)MIN_STEP_WIDTH, (unsigned)MAX_STEP_WIDTH);
01291                     } else if ((gop_frame_num - last_idr_frame_num) % 4 == 0) {
01292                         configuration_.picture_configuration.step_width_loq[LOQ_LEVEL_2] =
01293                             clamp(configuration_.picture_configuration.step_width_loq_orig[LOQ_LEVEL_2] *
01294                                       encoder_configuration_.delta_sw_mult_gop04 / 1000,
